1	import { test, expect } from "@playwright/test";
2	import path from "path";
3	import fs from "fs";
4	
5	const BASE = "http://localhost:3000";
6	
7	// Ensure test-results dir exists
8	const RESULTS_DIR = path.resolve(__dirname, "../test-results");
9	if (!fs.existsSync(RESULTS_DIR)) fs.mkdirSync(RESULTS_DIR, { recursive: true });
10	
11	test.describe("Pricing page parity — /pricing", () => {
12	  test("h1 contains both title lines", async ({ page }) => {
13	    await page.goto(`${BASE}/pricing`, { waitUntil: "domcontentloaded" });
14	    const h1 = page.locator("h1").first();
15	    await expect(h1).toBeVisible();
16	    const text = await h1.innerText();
17	    expect(text).toContain("Pick a Flexible Subscription.");
18	    expect(text).toContain("Get Predictable Output.");
19	  });
20	
21	  test("monthly tab — 3 pricing cards with correct prices", async ({ page }) => {
22	    await page.goto(`${BASE}/pricing`, { waitUntil: "domcontentloaded" });
23	    // Monthly is default — assert 3 prices
24	    await expect(page.getByText("$999/month").first()).toBeVisible();
25	    await expect(page.getByText("$1,999/month").first()).toBeVisible();
26	    await expect(page.getByText("$3,499/month").first()).toBeVisible();
27	  });
28	
29	  test("monthly CTA labels = 'Choose Plan' × 3", async ({ page }) => {
30	    await page.goto(`${BASE}/pricing`, { waitUntil: "domcontentloaded" });
31	    const ctaLinks = page.locator('a:has-text("Choose Plan")');
32	    await expect(ctaLinks).toHaveCount(3);
33	  });
34	
35	  test("monthly CTA hrefs contain portal.boldteq.com/services/{plan}", async ({ page }) => {
36	    await page.goto(`${BASE}/pricing`, { waitUntil: "domcontentloaded" });
37	    const ctaLinks = page.locator('a:has-text("Choose Plan")');
38	    const hrefs = await ctaLinks.evaluateAll((els) =>
39	      (els as HTMLAnchorElement[]).map((el) => el.href)
40	    );
41	    expect(hrefs).toHaveLength(3);
42	    for (const href of hrefs) {
43	      expect(href).toContain("portal.boldteq.com/services/");
44	    }
45	  });
46	
47	  test("quarterly tab — discounted prices + struck originals", async ({ page }) => {
48	    await page.goto(`${BASE}/pricing`, { waitUntil: "domcontentloaded" });
49	    await page.getByRole("button", { name: /quarterly/i }).click();
50	
51	    // Discounted prices
52	    await expect(page.getByText("$899/month").first()).toBeVisible();
53	    await expect(page.getByText("$1,799/month").first()).toBeVisible();
54	    await expect(page.getByText("$3,149/month").first()).toBeVisible();
55	
56	    // Struck-through originals (comparePrice elements)
57	    await expect(page.getByText("$999.00").first()).toBeVisible();
58	    await expect(page.getByText("$1,999.00").first()).toBeVisible();
59	    await expect(page.getByText("$3,499.00").first()).toBeVisible();
60	  });
61	
62	  test("quarterly CTA labels = 'Get Started' × 3", async ({ page }) => {
63	    await page.goto(`${BASE}/pricing`, { waitUntil: "domcontentloaded" });
64	    await page.getByRole("button", { name: /quarterly/i }).click();
65	    const ctaLinks = page.locator('a:has-text("Get Started")');
66	    await expect(ctaLinks).toHaveCount(3);
67	  });
68	
69	  test("annually tab — discounted prices + struck originals", async ({ page }) => {
70	    await page.goto(`${BASE}/pricing`, { waitUntil: "domcontentloaded" });
71	    await page.getByRole("button", { name: /annually/i }).click();
72	
73	    // Discounted prices
74	    await expect(page.getByText("$799/month").first()).toBeVisible();
75	    await expect(page.getByText("$1,599/month").first()).toBeVisible();
76	    await expect(page.getByText("$2,799/month").first()).toBeVisible();
77	
78	    // Struck-through originals
79	    await expect(page.getByText("$999.00").first()).toBeVisible();
80	    await expect(page.getByText("$1,999.00").first()).toBeVisible();
81	    await expect(page.getByText("$3,499.00").first()).toBeVisible();
82	  });
83	
84	  test("annually CTA labels = 'Get Started' × 3", async ({ page }) => {
85	    await page.goto(`${BASE}/pricing`, { waitUntil: "domcontentloaded" });
86	    await page.getByRole("button", { name: /annually/i }).click();
87	    const ctaLinks = page.locator('a:has-text("Get Started")');
88	    await expect(ctaLinks).toHaveCount(3);
89	  });
90	
91	  test("comparison table has exactly 9 data rows", async ({ page }) => {
92	    await page.goto(`${BASE}/pricing`, { waitUntil: "domcontentloaded" });
93	    // Each data row has a left cell with a strong label — count those
94	    // The table header row is separate; count only the data label cells
95	    const labelCells = page.locator('[class*="pricingTableCellLeft"]');
96	    await expect(labelCells).toHaveCount(9);
97	  });
98	
99	  test("ROI calculator section is present", async ({ page }) => {
100	    await page.goto(`${BASE}/pricing`, { waitUntil: "domcontentloaded" });
101	    // ROI section should exist — look for the heading or container
102	    const roiSection = page.locator('[class*="roi"], [id*="roi"], [data-testid*="roi"]').first();
103	    // Fallback: look for known ROI calc text
104	    const roiHeading = page.getByText(/roi|return on investment|calculate/i).first();
105	    // Either the section wrapper or a visible heading must exist
106	    const sectionVisible = await roiSection.isVisible().catch(() => false);
107	    const headingVisible = await roiHeading.isVisible().catch(() => false);
108	    expect(sectionVisible || headingVisible).toBe(true);
109	  });
110	
111	  // ── Viewport screenshot suite ─────────────────────────────────────────────
112	  for (const viewport of [
113	    { name: "1440", width: 1440, height: 900 },
114	    { name: "1280", width: 1280, height: 800 },
115	    { name: "991", width: 991, height: 768 },
116	    { name: "767", width: 767, height: 900 },
117	    { name: "479", width: 479, height: 900 },
118	  ]) {
119	    test(`screenshot at ${viewport.name}px`, async ({ page }) => {
120	      await page.setViewportSize({ width: viewport.width, height: viewport.height });
121	      await page.goto(`${BASE}/pricing`, { waitUntil: "networkidle" });
122	      const filePath = path.join(RESULTS_DIR, `pricing-${viewport.name}.png`);
123	      await page.screenshot({ path: filePath, fullPage: true });
124	      expect(fs.existsSync(filePath)).toBe(true);
125	    });
126	  }
127	});
